const searchTagsLexicalPage = `-- name: SearchTagsLexicalPage :many
WITH prefix_all AS (
  SELECT
    t.id,
    t.display,
    t.item_count,
    t.last_used_at,
    (CASE
      WHEN t.normalized LIKE $2::text ESCAPE '\' THEN 3
      ELSE 2
    END)::int AS tier,
    (CASE
      WHEN NOT $3::bool THEN
        (CASE
          WHEN immutable_unaccent($4::text) ~ '^[[:alnum:]]+$' THEN
            (CASE
              WHEN t.tag_unaccent ~ ('(^|[^[:alnum:]])' || immutable_unaccent($4::text) || '($|[^[:alnum:]])') THEN 1.0::float8
              ELSE round(
                (
                  char_length(immutable_unaccent($4::text))::numeric
                  / (char_length(immutable_unaccent($4::text)) + 1)::numeric
                ),
                2
              )::float8
            END)
          ELSE 0.0::float8
        END)
      ELSE
        round(
          GREATEST(
            similarity(t.tag_unaccent, immutable_unaccent($4::text)),
            word_similarity(immutable_unaccent($4::text), t.tag_unaccent)
          )::numeric,
          2
        )::float8
    END) AS score
  FROM tag AS t
  WHERE t.user_id = $5
    AND t.deleted_at IS NULL
    AND (
      $6::uuid IS NULL
      OR $7::int >= 2
    )
    AND (
      t.normalized LIKE $2::text ESCAPE '\'
      OR t.tag_unaccent LIKE (
        replace(
          replace(
            replace(immutable_unaccent($4::text), '\', '\\'),
            '%',
            '\%'
          ),
          '_',
          '\_'
        ) || '%'
      ) ESCAPE '\'
    )
),
prefix_ranked AS (
  SELECT
    p.id,
    p.display,
    p.item_count,
    p.last_used_at,
    p.tier,
    p.score
  FROM prefix_all AS p
  WHERE
    $6::uuid IS NULL
    OR p.tier < $7::int
    OR (
      p.tier = $7::int
      AND p.score < $8::float8
    )
    OR (
      p.tier = $7::int
      AND p.score = $8::float8
      AND p.last_used_at < $9::timestamptz
    )
    OR (
      p.tier = $7::int
      AND p.score = $8::float8
      AND p.last_used_at = $9::timestamptz
      AND p.item_count < $10::int
    )
    OR (
      p.tier = $7::int
      AND p.score = $8::float8
      AND p.last_used_at = $9::timestamptz
      AND p.item_count = $10::int
      AND p.id > $6::uuid
    )
  ORDER BY
    p.tier DESC,
    p.score DESC,
    p.last_used_at DESC,
    p.item_count DESC,
    p.id ASC
  LIMIT $1
),
fuzzy_all AS (
  SELECT
    t.id,
    t.display,
    t.item_count,
    t.last_used_at,
    1::int AS tier,
    round(
      GREATEST(
        similarity(t.tag_unaccent, immutable_unaccent($4::text)),
        word_similarity(immutable_unaccent($4::text), t.tag_unaccent)
      )::numeric,
      2
    )::float8 AS score
  FROM tag AS t
  WHERE $3::bool
    AND t.user_id = $5
    AND t.deleted_at IS NULL
    AND (
      t.tag_unaccent % immutable_unaccent($4::text)
      OR immutable_unaccent($4::text) <% t.tag_unaccent
    )
    AND NOT (
      t.normalized LIKE $2::text ESCAPE '\'
      OR t.tag_unaccent LIKE (
        replace(
          replace(
            replace(immutable_unaccent($4::text), '\', '\\'),
            '%',
            '\%'
          ),
          '_',
          '\_'
        ) || '%'
      ) ESCAPE '\'
    )
),
fuzzy_ranked AS (
  SELECT
    f.id,
    f.display,
    f.item_count,
    f.last_used_at,
    f.tier,
    f.score
  FROM fuzzy_all AS f
  WHERE
    $6::uuid IS NULL
    OR f.tier < $7::int
    OR (
      f.tier = $7::int
      AND f.score < $8::float8
    )
    OR (
      f.tier = $7::int
      AND f.score = $8::float8
      AND f.last_used_at < $9::timestamptz
    )
    OR (
      f.tier = $7::int
      AND f.score = $8::float8
      AND f.last_used_at = $9::timestamptz
      AND f.item_count < $10::int
    )
    OR (
      f.tier = $7::int
      AND f.score = $8::float8
      AND f.last_used_at = $9::timestamptz
      AND f.item_count = $10::int
      AND f.id > $6::uuid
    )
  ORDER BY
    f.score DESC,
    f.last_used_at DESC,
    f.item_count DESC,
    f.id ASC
  LIMIT GREATEST(0, $1::int - (SELECT count(*)::int FROM prefix_ranked))
)
SELECT
  combined.id,
  combined.display,
  combined.item_count,
  combined.last_used_at,
  combined.tier,
  combined.score
FROM (
  SELECT
    prefix_ranked.id,
    prefix_ranked.display,
    prefix_ranked.item_count,
    prefix_ranked.last_used_at,
    prefix_ranked.tier,
    prefix_ranked.score
  FROM prefix_ranked
  UNION ALL
  SELECT
    fuzzy_ranked.id,
    fuzzy_ranked.display,
    fuzzy_ranked.item_count,
    fuzzy_ranked.last_used_at,
    fuzzy_ranked.tier,
    fuzzy_ranked.score
  FROM fuzzy_ranked
) AS combined
ORDER BY
  combined.tier DESC,
  combined.score DESC,
  combined.last_used_at DESC,
  combined.item_count DESC,
  combined.id ASC
LIMIT $1
`

